INSERT INTO zc_jobs.job(lane,id,task,payload,job_key,lock_group,max_attempts,running,lease_until) SELECT 'bulk',pgmq.send('zeepcentraal_bulk','{}'), 'fixture',jsonb_build_object('padding',repeat('x',1000)),'key:'||n,'group:'||(n%56),3,n<=200 AND n%56<24,CASE WHEN n<=200 AND n%56<24 THEN clock_timestamp()+interval '1 hour' END FROM generate_series(1,37000) n; ANALYZE zc_jobs.job; ANALYZE pgmq.q_zeepcentraal_bulk
